#!/usr/bin/env node

/**

Rebuild unpushed archive changes as byte-capped commits and push each commit.

Dry run (default):

node scripts/push-archive-in-batches.mjs

Execute:

node scripts/push-archive-in-batches.mjs --execute

Optional environment variables:

ARCHIVE_BASE_REF=origin/content/source-library-import

ARCHIVE_SOURCE_REF=HEAD

ARCHIVE_TARGET_BRANCH=content/source-library-import-batched

ARCHIVE_BATCH_BYTES=250000000

ARCHIVE_LFS_THRESHOLD_BYTES=95000000

ARCHIVE_PUSH_INTERVAL_MS=11000

GITHUB_TOKEN=...  (used without writing the token to Git configuration)
 */

import {
  copyFileSync,
  cpSync,
  existsSync,
  lstatSync,
  mkdirSync,
  mkdtempSync,
  readlinkSync,
  rmSync,
  symlinkSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { spawnSync } from 'node:child_process';

const execute = process.argv.includes('--execute');
const baseRef =
  process.env.ARCHIVE_BASE_REF ?? 'origin/content/source-library-import';
const sourceRef = process.env.ARCHIVE_SOURCE_REF ?? 'HEAD';
const targetBranch =
  process.env.ARCHIVE_TARGET_BRANCH ?? 'content/source-library-import-batched';
const batchLimit = Number(
  process.env.ARCHIVE_BATCH_BYTES ?? 250_000_000,
);
const lfsThreshold = Number(
  process.env.ARCHIVE_LFS_THRESHOLD_BYTES ?? 95_000_000,
);
const githubBlobLimit = 100_000_000;
const pushIntervalMs = Number(
  process.env.ARCHIVE_PUSH_INTERVAL_MS ?? 11_000,
);
const rootResult = spawnSync('git', ['rev-parse', '--show-toplevel'], {
  cwd: process.cwd(),
  encoding: 'utf8',
  maxBuffer: 100 * 1024 * 1024,
});
if (rootResult.status !== 0) {
  fail(rootResult.stderr.trim() || 'This command must run inside a Git worktree.');
}
const repositoryRoot = rootResult.stdout.trim();

if (!Number.isSafeInteger(batchLimit) || batchLimit <= 0) {
  fail('ARCHIVE_BATCH_BYTES must be a positive integer.');
}
if (!Number.isSafeInteger(lfsThreshold) || lfsThreshold <= 0) {
  fail('ARCHIVE_LFS_THRESHOLD_BYTES must be a positive integer.');
}

git(['rev-parse', '--verify', ${baseRef}^{commit}], { capture: true });
git(['rev-parse', '--verify', ${sourceRef}^{commit}], { capture: true });

const dirty = gitText(['status', '--porcelain=v1']);
if (dirty) {
  console.warn(
    'Notice: the worktree is dirty. Only committed range changes and current source-library files will be copied; unrelated changes are excluded.',
  );
}

const committedDeletions = gitNull([
  'diff',
  '--name-only',
  '-z',
  '--diff-filter=D',
  ${baseRef}..${sourceRef},
]);
const deletions = [...new Set(committedDeletions)];
if (deletions.length > 0) {
  fail(
    Refusing to continue because the selected range deletes ${deletions.length} path(s).,
  );
}

const committedPaths = gitNull([
  'diff',
  '--name-only',
  '-z',
  '--diff-filter=ACMRT',
  ${baseRef}..${sourceRef},
]);
const untrackedArchivePaths = gitNull([
  'ls-files',
  '--others',
  '--exclude-standard',
  '-z',
  '--',
  'source-library',
]);
const paths = [
  ...new Set([
    ...committedPaths,
    ...untrackedArchivePaths,
  ]),
];
if (paths.length === 0) {
  fail(No changed files found in ${baseRef}..${sourceRef}.);
}

const files = paths.map((path) => {
  const absolutePath = resolve(repositoryRoot, path);
  if (!existsSync(absolutePath)) {
    fail(Expected source path is missing from the worktree: ${path});
  }

return {
    path,
    bytes: diskSize(absolutePath),
    useLfs: diskSize(absolutePath) >= lfsThreshold,
  };
});

const oversized = files.filter((file) => file.bytes >= githubBlobLimit);
const batches = firstFitDecreasing(files, batchLimit);

console.log(Source range: ${baseRef}..${sourceRef});
console.log(Files: ${files.length});
console.log(Batches: ${batches.length});
console.log(Per-commit regular-Git payload ceiling: ${formatBytes(batchLimit)});
console.log(Git LFS threshold: ${formatBytes(lfsThreshold)});
console.log(
  GitHub-blocked regular blobs: ${oversized.length} (these require Git LFS),
);
console.log('');

batches.forEach((batch, index) => {
  const sourceBytes = batch.reduce((total, file) => total + file.bytes, 0);
  const gitBytes = batch.reduce(
    (total, file) => total + (file.useLfs ? 200 : file.bytes),
    0,
  );
  const lfsCount = batch.filter((file) => file.useLfs).length;
  console.log(
    ${String(index + 1).padStart(3, '0')}: ${batch.length} files, ${formatBytes(gitBytes)} Git payload, ${formatBytes(sourceBytes)} source, ${lfsCount} LFS,
  );
});

if (!execute) {
  console.log('');
  console.log('Dry run only. Re-run with --execute to create and push the batched branch.');
  process.exit(0);
}

if (oversized.length > 0 && !hasGitLfs()) {
  fail(
    'Git LFS is required for files at or above GitHub’s 100 MB regular-blob limit, but git-lfs is not installed.',
  );
}

if (gitExit(['show-ref', '--verify', '--quiet', refs/heads/${targetBranch}]) === 0) {
  fail(Local target branch already exists: ${targetBranch});
}

const worktree = mkdtempSync(join(tmpdir(), 'portfolio-archive-batches-'));
let worktreeAdded = false;

try {
  git(['worktree', 'add', '-b', targetBranch, worktree, baseRef]);
  worktreeAdded = true;

if (files.some((file) => file.useLfs)) {
    git(['lfs', 'install', '--local'], { cwd: worktree });
  }

for (const [index, batch] of batches.entries()) {
    const label = String(index + 1).padStart(3, '0');
    const lfsFiles = batch.filter((file) => file.useLfs);

for (const file of batch) {
  copyPath(
    resolve(repositoryRoot, file.path),
    resolve(worktree, file.path),
  );
}

for (const file of lfsFiles) {
  git(['lfs', 'track', file.path], { cwd: worktree });
}

if (lfsFiles.length > 0) {
  git(['add', '--', '.gitattributes'], { cwd: worktree });
}
git(['add', '--', ...batch.map((file) => file.path)], { cwd: worktree });
git(
  [
    'commit',
    '-m',
    `Archive import batch ${label}/${String(batches.length).padStart(3, '0')}`,
  ],
  { cwd: worktree },
);
push(worktree);
if (index < batches.length - 1 && pushIntervalMs > 0) {
  await new Promise((resolveWait) => setTimeout(resolveWait, pushIntervalMs));
}

}

console.log('');
  console.log(Completed: ${targetBranch});
} finally {
  if (worktreeAdded) {
    git(['worktree', 'remove', '--force', worktree]);
  } else {
    rmSync(worktree, { recursive: true, force: true });
  }
}

function firstFitDecreasing(input, limit) {
  const result = [];
  const sorted = [...input].sort(
    (left, right) =>
      right.bytes - left.bytes || left.path.localeCompare(right.path),
  );

for (const file of sorted) {
    if (!file.useLfs && file.bytes > limit) {
      fail(
        ${file.path} is larger than the batch ceiling. Raise ARCHIVE_BATCH_BYTES or lower ARCHIVE_LFS_THRESHOLD_BYTES.,
      );
    }

const accountingBytes = file.useLfs ? 200 : file.bytes;
let destination = result.find(
  (batch) =>
    batch.reduce(
      (total, item) => total + (item.useLfs ? 200 : item.bytes),
      0,
    ) +
      accountingBytes <=
    limit,
);

if (!destination) {
  destination = [];
  result.push(destination);
}
destination.push(file);

}

return result;
}

function diskSize(path) {
  const stat = lstatSync(path);
  return stat.isDirectory() ? 0 : stat.size;
}

function copyPath(source, destination) {
  const stat = lstatSync(source);
  mkdirSync(dirname(destination), { recursive: true });

if (stat.isSymbolicLink()) {
    rmSync(destination, { force: true });
    symlinkSync(readlinkSync(source), destination);
  } else if (stat.isDirectory()) {
    cpSync(source, destination, { recursive: true });
  } else {
    copyFileSync(source, destination);
  }
}

function hasGitLfs() {
  return gitExit(['lfs', 'version']) === 0;
}

function push(cwd) {
  const token = process.env.GITHUB_TOKEN;
  const args = [];

if (token) {
    const credential = Buffer.from(x-access-token:${token}).toString('base64');
    args.push('-c', http.extraHeader=Authorization: Basic ${credential});
  }

args.push('push', '-u', 'origin', HEAD:${targetBranch});
  git(args, { cwd });
}

function git(args, options = {}) {
  const result = spawnSync('git', args, {
    cwd: options.cwd ?? repositoryRoot,
    encoding: 'utf8',
    stdio: options.capture ? 'pipe' : 'inherit',
    maxBuffer: 100 * 1024 * 1024,
  });

if (result.status !== 0) {
    fail(git ${args[0]} failed with exit code ${result.status}.);
  }
  return result;
}

function gitText(args) {
  const result = spawnSync('git', args, {
    cwd: repositoryRoot,
    encoding: 'utf8',
    maxBuffer: 100 * 1024 * 1024,
  });
  if (result.status !== 0) {
    fail(result.stderr.trim() || git ${args[0]} failed.);
  }
  return result.stdout.trim();
}

function gitNull(args) {
  const result = spawnSync('git', args, {
    cwd: repositoryRoot,
    encoding: 'buffer',
    maxBuffer: 100 * 1024 * 1024,
  });
  if (result.status !== 0) {
    fail(result.stderr.toString().trim() || git ${args[0]} failed.);
  }
  return result.stdout
    .toString()
    .split('\0')
    .filter(Boolean);
}

function gitExit(args) {
  return spawnSync('git', args, {
    cwd: repositoryRoot,
    stdio: 'ignore',
  }).status;
}

function formatBytes(bytes) {
  return ${(bytes / 1_000_000).toFixed(1)} MB;
}

function fail(message) {
  console.error(Error: ${message});
  process.exit(1);
}
